trend-line:
import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var D = [12, 14, 13, 17, 16, 19, 18, 22, 21];
    return <div className="dssparkline-example">
    <style>{exampleStyles}</style>
    <S.DsSparkline data={D} dot={true}/>
    </div>;
}

const exampleStyles = ".dssparkline-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dssparkline-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dssparkline-example p{margin:0}\n";

export { App as Example };

